import { NextResponse } from "next/server"
import Groq from "groq-sdk"
import { generateSmartLinks, extractPdfUrl, categorizeLinkType, generateGoogleSearchUrl } from "@/lib/google-search"

const groq = new Groq({
  apiKey: process.env.GROQ_API_KEY,
})

export async function POST(req: Request) {
  try {
    const { institution, grade, subject } = await req.json()

    if (!institution || !grade || !subject) {
      return NextResponse.json({ error: "Missing required fields" }, { status: 400 })
    }

    console.log('[Discovery] Searching for:', institution, grade, subject)

    // Generate smart portal links based on URL patterns
    const smartLinks = generateSmartLinks(institution, grade, subject)

    const papers = smartLinks.map(result => ({
      title: result.title,
      url: result.link,
      source: result.link.includes('selfstudys') ? 'SelfStudys'
        : result.link.includes('shaalaa') ? 'Shaalaa'
          : result.link.includes('vedantu') ? 'Vedantu'
            : 'Web',
      type: categorizeLinkType(result.link),
      googleFallback: generateGoogleSearchUrl(institution, grade, subject),
    }))

    console.log('[Discovery] Generated', papers.length, 'smart links')

    // Always generate career relevance
    const careerPrompt = `
      For ${subject} at ${institution} ${grade} level, provide career relevance data.
      
      Return JSON:
      {
        "companies": ["Top Company 1", "Top Company 2"],
        "roles": ["Job Role 1", "Job Role 2"],
        "marketDemand": 85,
        "summary": "One sentence on career value of mastering this subject."
      }
    `

    const careerCompletion = await groq.chat.completions.create({
      messages: [{ role: "user", content: careerPrompt }],
      model: "llama-3.3-70b-versatile",
      response_format: { type: "json_object" },
    })

    const career = JSON.parse(careerCompletion.choices[0].message.content || "{}")

    return NextResponse.json({ papers, career })
  } catch (error) {
    console.error("Discovery API Error:", error)
    return NextResponse.json({ error: "Failed to discover papers" }, { status: 500 })
  }
}
